def topk_route(logits: Tensor, k: int) -> tuple[Tensor, Tensor]:
    probs = torch.softmax(logits, dim=-1)
    weights, indices = torch.topk(probs, k, dim=-1)
    return indices, weights / weights.sum(dim=-1, keepdim=True)

